def render_page_header(
    title,
    subtitle="",
    kicker=""
):
    title_safe = html_module.escape(
        str(title)
    )
    kicker_html = ""

    if kicker:
        kicker_safe = html_module.escape(
            str(kicker)
        )
        kicker_html = (
            f'<div class="sp-kicker">'
            f'{kicker_safe}</div>'
        )

    subtitle_html = ""

    if subtitle:
        subtitle_safe = html_module.escape(
            str(subtitle)
        )
        subtitle_html = (
            f'<p>{subtitle_safe}</p>'
        )

    header_html = (
        f'<div class="sp-page-header">'
        f'{kicker_html}'
        f'<h1>{title_safe}</h1>'
        f'{subtitle_html}'
        f'</div>'
    )

    st.markdown(
        header_html,
        unsafe_allow_html=True
    )


def sidebar_nav_button(
    label,
    page_name,
    key
):
    is_active = (
        st.session_state.current_page
        == page_name
    )

    if st.button(
        label,
        use_container_width=True,
        icon=None,
        type=(
            "primary"
            if is_active
            else "secondary"
        ),
        key=key,
    ):

        st.session_state.current_page = (
            page_name
        )

        st.rerun()




# ============================================================
# SUPABASE DATA CLIENT (service_role — server-side only)
# Used by student-data helpers. Do not use this client for Auth.
# Email/password Auth uses a separate per-session publishable-key client.
# ============================================================

@st.cache_resource
def init_supabase():
    return create_client(
        st.secrets["supabase"]["url"],
        st.secrets["supabase"]["service_key"]
    )


try:
    supabase = init_supabase()
    supabase_connected = True

except Exception:
    logger.exception(
        "Supabase client initialization failed"
    )
    supabase = None
    supabase_connected = False


