# ============================================================
# HELPER FUNCTIONS
# ============================================================

def opportunity_text(
    value,
    fallback=""
):

    if value is None:
        return fallback

    try:

        if pd.isna(
            value
        ):
            return fallback

    except Exception:
        pass

    text = str(
        value
    ).strip()

    if (
        not text
        or
        text.lower() == "nan"
    ):
        return fallback

    return text


def opportunity_field(
    opportunity,
    *keys,
    fallback=""
):

    for key in keys:

        text = opportunity_text(
            opportunity.get(
                key
            ),
            ""
        )

        if (
            text
            and
            text.lower() not in {
                "check official eligibility",
                "unknown / check official site",
                "not publicly reported",
                "check official site",
                "not specified",
                "unknown",
                "not stated",
                "nan",
                "none"
            }
        ):
            return text

    return fallback


def opportunity_cost_display(
    opportunity
):

    cost = opportunity_field(
        opportunity,
        "cost",
        "cost_category",
        fallback="Check official site"
    )

    tuition = opportunity_field(
        opportunity,
        "tuition_cost",
        fallback=""
    )

    if cost.lower() == "free":
        return "Free"

    if cost.lower() in {
        "tuition required",
        "tuition-based",
        "paid program"
    }:

        if tuition:

            if tuition.lower().startswith(
                "tuition required"
            ):
                return tuition

            return (
                "Tuition required: "
                + tuition
            )

        return "Paid program"

    if cost.lower() in {
        "unknown / check official site",
        "unknown"
    }:

        if tuition:
            return tuition

        return "Check official site"

    return cost


def opportunity_acceptance_source_label(
    opportunity
):

    confidence = opportunity_text(
        opportunity.get(
            "acceptance_rate_confidence"
        ),
        ""
    )

    if confidence.startswith(
        "Estimated"
    ):
        return "Unofficial estimate"

    mapped = CONFIDENCE_SOURCE_LABEL.get(
        confidence,
        ""
    )

    if mapped:
        return mapped

    source = opportunity_field(
        opportunity,
        "acceptance_rate_source",
        fallback=""
    )

    if source:
        return source

    return ""


def opportunity_stat_html(
    label,
    value,
    note="",
    html_value=False
):

    note_html = ""

    if note:

        note_html = (
            '<div class="sp-rate-source">'
            + html_module.escape(
                str(
                    note
                )
            )
            + '</div>'
        )

    if html_value:
        value_html = str(
            value
        )
    else:
        value_html = html_module.escape(
            str(
                value
            )
        )

    return (
        '<div class="sp-deadline-stat">'
        '<div class="sp-deadline-stat-label">'
        + html_module.escape(
            str(
                label
            )
        )
        + '</div>'
        '<div class="sp-deadline-stat-value">'
        + value_html
        + note_html
        + '</div>'
        '</div>'
    )


def opportunity_acceptance_display(
    opportunity
):

    rate = opportunity_field(
        opportunity,
        "acceptance_rate",
        fallback=""
    )

    confidence = opportunity_text(
        opportunity.get(
            "acceptance_rate_confidence"
        ),
        ""
    )

    if not rate:
        rate = "Estimated — see program details"

    rate_lower = rate.lower()
    is_estimated = (
        confidence.startswith(
            "Estimated"
        )
        or
        "estimated" in rate_lower
        or
        "unofficial" in rate_lower
    )

    if (
        is_estimated
        and
        "(estimated)" not in rate_lower
        and
        "estimated" not in rate_lower
    ):
        rate = f"{rate} (estimated)"

    return rate


def opportunity_financial_aid_display(
    opportunity
):

    aid = opportunity_field(
        opportunity,
        "financial_aid_status",
        "financial_aid",
        fallback=""
    )

    cost = opportunity_cost_display(
        opportunity
    )

    cost_category = opportunity_text(
        opportunity.get(
            "cost_category"
        ),
        ""
    ).lower()

    if not aid:
        if cost == "Free" or cost_category == "free":
            return "Free"
        if "stipend" in cost_category or "paid" in cost_category:
            return "Paid"
        return "Unknown"

    aid_lower = aid.lower()

    if (
        cost == "Free"
        and
        aid_lower in {
            "not needed",
            "not needed — program is free",
            "not needed — program is completely free",
            "not needed — fully funded",
            "not needed — program is fully funded",
            "not needed — program is fully funded / full scholarship",
            "not needed — fully funded / full scholarship",
        }
    ):
        return (
            "Free program; provides support for accepted students "
            "(verify details)"
            if "arise" in opportunity_text(
                opportunity.get(
                    "name"
                ),
                ""
            ).lower()
            else "Free"
        )

    if aid_lower.startswith(
        "unknown"
    ) or aid_lower in {
        "check official site",
        "check official cycle details",
        "check official 2027 cycle details",
        "no aid stated",
        "not stated",
    }:
        if cost == "Free" or cost_category == "free":
            return "Free"
        if "financial aid" in aid_lower or "waiver" in aid_lower:
            return "Partial aid"
        return "Unknown"

    if (
        "full" in aid_lower
        and
        (
            "aid" in aid_lower
            or
            "scholarship" in aid_lower
            or
            "waiver" in aid_lower
            or
            "funded" in aid_lower
        )
        and
        "partial" not in aid_lower
    ):
        if cost == "Free":
            return "Free"
        return aid

    return aid


def opportunity_transparency_stats_html(
    opportunity
):

    eligibility = opportunity_field(
        opportunity,
        "eligibility_summary",
        "requirements",
        "application_requirements",
        fallback="Check official eligibility"
    )

    cost = opportunity_cost_display(
        opportunity
    )

    aid = opportunity_financial_aid_display(
        opportunity
    )

    stipend = opportunity_field(
        opportunity,
        "stipend_display",
        "stipend",
        "paid_status",
        fallback="Check official site"
    )

    rate = opportunity_acceptance_display(
        opportunity
    )

    source_label = opportunity_acceptance_source_label(
        opportunity
    )

    if (
        source_label.lower()
        in {
            "not publicly reported",
            "not available",
            ""
        }
        and
        "(estimated)" in rate.lower()
    ):
        source_label = "Unofficial estimate"

    return (
        opportunity_stat_html(
            "Eligibility",
            eligibility
        )
        + opportunity_stat_html(
            "Cost",
            cost
        )
        + opportunity_stat_html(
            "Financial Aid",
            aid
        )
        + opportunity_stat_html(
            "Stipend",
            stipend
        )
        + opportunity_stat_html(
            "Acceptance Rate",
            rate,
            source_label
        )
    )


def opportunity_window_status(
    opportunity
):

    raw_status = opportunity_text(
        opportunity.get(
            "application_status",
            ""
        )
    )

    status_lower = raw_status.lower()

    deadline_dt = parse_confirmed_deadline(
        opportunity.get(
            "deadline"
        )
    )

    days_left = None

    if deadline_dt is not None:

        now_local = datetime.now(
            timezone.utc
        )

        if deadline_dt.tzinfo is None:

            compare_deadline = deadline_dt.replace(
                tzinfo=timezone.utc
            )

        else:

            compare_deadline = deadline_dt.astimezone(
                timezone.utc
            )

        days_left = (
            compare_deadline.date()
            -
            now_local.date()
        ).days

    if (
        days_left is not None
        and
        days_left < 0
    ):
        return "CLOSED"

    if "closed" in status_lower:
        return "CLOSED"

    if (
        "open now" in status_lower
        or
        status_lower == "open"
        or
        status_lower.startswith("open ")
    ):
        return "OPEN NOW"

    if (
        "future cycle" in status_lower
        or
        "opens " in status_lower
        or
        "not yet" in status_lower
        or
        "upcoming" in status_lower
        or
        status_lower == "future"
    ):
        return "UPCOMING"

    if (
        days_left is not None
        and
        days_left >= 0
    ):
        return "OPEN NOW"

    return "UPCOMING"


def application_cycle_badge(
    opportunity
):

    raw_status = opportunity_text(
        opportunity.get(
            "application_status",
            ""
        )
        if opportunity is not None
        else ""
    )

    status_lower = raw_status.lower()
    window = "UPCOMING"

    if opportunity is not None:

        try:

            window = opportunity_window_status(
                opportunity
            )

        except Exception:

            window = "UPCOMING"

    if (
        window == "CLOSED"
        or
        "closed" in status_lower
    ):
        return (
            "CLOSED",
            "sp-deadline-badge-closed"
        )

    if (
        window == "OPEN NOW"
        or
        "open now" in status_lower
        or
        status_lower == "open"
    ):
        return (
            "OPEN NOW",
            "sp-deadline-badge-open"
        )

    if (
        "future cycle" in status_lower
        or
        status_lower == "future"
        or
        "opens " in status_lower
        or
        "not yet" in status_lower
    ):
        return (
            "FUTURE CYCLE",
            "sp-deadline-badge-future"
        )

    if (
        window == "UPCOMING"
        or
        "upcoming" in status_lower
    ):
        return (
            "UPCOMING",
            "sp-deadline-badge-upcoming"
        )

    return (
        "FUTURE CYCLE",
        "sp-deadline-badge-future"
    )


