def stem_fields_for_opportunity_area(area_name):
    """Return the concrete STEM fields covered by a broad opportunity search area."""

    area = str(area_name or "").strip()
    if not area or area == OPPORTUNITY_STEM_AREA_ALL:
        return []

    for group_name, fields in STEM_FIELD_GROUPS:
        if group_name == area:
            return list(fields)

    return []


def opportunity_field_match_set(fields_value):
    """
    Build the expanded set of STEM labels that an opportunity can match.
    Uses raw tags, canonical names, related fields, and research-area helpers.
    """

    raw_fields = [
        item.strip()
        for item in str(fields_value or "").split(";")
        if item.strip()
    ]
    matched = set(raw_fields)
    matched.update(canonicalize_stem_field_list(raw_fields))
    matched.update(research_areas_from_fields(fields_value))
    matched.update(expand_stem_fields(raw_fields))
    matched.discard("")
    return matched


def opportunity_matches_stem_selection(fields_value, selected_fields):
    """True when any selected STEM field (with expansion) overlaps the opportunity."""

    selected = [
        str(item).strip()
        for item in (selected_fields or [])
        if str(item).strip()
    ]
    if not selected:
        return True

    selected_expanded = expand_stem_fields(selected)
    opportunity_expanded = opportunity_field_match_set(fields_value)
    return bool(selected_expanded.intersection(opportunity_expanded))


def opportunity_matches_format(format_value, selected_formats):
    """Match one or more student-selected delivery formats using OR logic."""

    selected = {
        str(value).strip().lower()
        for value in (selected_formats or [])
        if str(value).strip()
    }
    if not selected:
        return True

    format_text = str(format_value or "").strip().lower()
    if not format_text:
        return False

    if "hybrid" in format_text:
        opportunity_format = "hybrid"
    elif any(
        token in format_text
        for token in ["online", "virtual", "remote"]
    ):
        opportunity_format = "online"
    elif any(
        token in format_text
        for token in ["in person", "in-person", "onsite", "on-site"]
    ):
        opportunity_format = "in person"
    else:
        return False

    return opportunity_format in selected


def expand_stem_fields(values):

    expanded = set()

    skip = {
        "not sure yet",
        "i'm not sure yet",
        "i am not sure yet"
    }

    for value in values or []:
        text = str(value or "").strip()

        if not text or text.lower() in skip:
            continue

        canonical = canonicalize_stem_field(text)
        expanded.add(text)
        expanded.add(canonical)
        expanded.update(
            RELATED_STEM_FIELDS.get(text, [])
        )
        expanded.update(
            RELATED_STEM_FIELDS.get(canonical, [])
        )
        expanded.update(
            STEM_FIELD_PARENTS.get(text, [])
        )
        expanded.update(
            STEM_FIELD_PARENTS.get(canonical, [])
        )

    expanded.discard("")
    return expanded


def research_areas_from_fields(fields_value):

    tokens = [
        item.strip().lower()
        for item in str(fields_value or "").split(";")
        if item.strip()
    ]

    areas = set()

    for token in tokens:
        canonical = canonicalize_stem_field(token)
        if canonical:
            areas.add(canonical)

    def token_matches(*needles):
        for token in tokens:
            for needle in needles:
                if token == needle or needle in token:
                    return True
        return False

    if token_matches("artificial intelligence", "machine learning") or "ai" in tokens:
        areas.add("Artificial Intelligence")
        areas.add("Machine Learning")
    if token_matches("computer science"):
        areas.add("Computer Science")
    if token_matches("engineering") and not any(
        "financial engineering" in token or token in {"fintech", "architecture"}
        for token in tokens
    ):
        # Avoid treating financial engineering / architecture tags as general Engineering.
        if any(
            token == "engineering"
            or (
                "engineering" in token
                and "financial" not in token
            )
            for token in tokens
        ):
            areas.add("Engineering")
            areas.add("General Engineering / Undecided Engineering")
    if token_matches("biomedical", "bioengineering"):
        areas.add("Biomedical Science")
        areas.add("Biomedical Engineering")
        areas.add("Bioengineering")
    if token_matches("biology"):
        areas.add("Biology")
    if token_matches("neuroscience", "neurology"):
        areas.add("Neuroscience")
    if token_matches("cancer"):
        areas.add("Cancer Research")
    if token_matches("data science", "data analysis"):
        areas.add("Data Science")
    if token_matches("statistics", "biostatistics"):
        areas.add("Statistics")
        areas.add("Data Science")
    if token_matches("mathematics") or "math" in tokens:
        areas.add("Mathematics")
    if token_matches("applied math", "applied mathematics"):
        areas.add("Applied Mathematics")
    if token_matches("physics"):
        areas.add("Physics")
    if token_matches("applied physics", "engineering physics"):
        areas.add("Applied Physics")
        areas.add("Physics")
    if token_matches("quantum"):
        areas.add("Physics")
        areas.add("Applied Physics")
    if token_matches("nuclear science", "particle physics"):
        areas.add("Nuclear Science")
        areas.add("Physics")
        areas.add("Applied Physics")
    if token_matches("astronomy", "astrophysics"):
        areas.add("Astronomy / Astrophysics")
        areas.add("Astrophysics / Astronomy")
        areas.add("Space Science")
    if token_matches("water treatment", "renewable energy"):
        areas.add("Environmental Engineering")
        areas.add("Environmental Science")
    if token_matches("chemistry"):
        areas.add("Chemistry")
    if token_matches("biochemistry"):
        areas.add("Biochemistry")
        areas.add("Biology")
        areas.add("Chemistry")
    if token_matches("environmental studies", "sustainability"):
        areas.add("Environmental Studies / Sustainability")
        areas.add("Environmental Science")
    if token_matches("environmental", "ecology"):
        areas.add("Environmental Science")
        areas.add("Ecology")
    if token_matches("earth science", "geoscience", "geology"):
        areas.add("Earth Science")
        areas.add("Earth Science / Geoscience")
        areas.add("Geology")
        areas.add("Earth / Climate Science")
    if token_matches("operations research"):
        areas.add("Operations Research")
        areas.add("Applied Mathematics")
        areas.add("Statistics")
        areas.add("Data Science")
    if token_matches("climate"):
        areas.add("Climate Science")
        areas.add("Earth / Climate Science")
    if token_matches("bioinformatics", "computational biology"):
        areas.add("Bioinformatics / Computational Biology")
    if token_matches("cognitive science"):
        areas.add("Cognitive Science")
        areas.add("Neuroscience")
    if token_matches("computational science"):
        areas.add("Computational Science")
        areas.add("Computer Science")
