def save_profile(
    user_sub,
    email,
    profile
):

    if not supabase_can_write():
        return False

    if not require_user_sub(user_sub):
        notify_student_data_error()
        return False

    now = datetime.now(
        timezone.utc
    ).isoformat()

    # Never change user_sub or email on existing rows.
    update_data = {
        "first_name":
            profile["first_name"],

        "middle_name":
            profile["middle_name"],

        "last_name":
            profile["last_name"],

        "age":
            int(profile["age"]),

        "grade":
            profile["grade"],

        "borough":
            profile["borough"],

        "interests":
            list_to_text(
                profile["interests"]
            ),

        "experience_areas":
            list_to_text(
                profile["experience_areas"]
            ),

        "goals":
            list_to_text(
                profile["goals"]
            ),

        "exploration_stage":
            profile["exploration_stage"],

        "confidence":
            int(profile["confidence"]),

        "weekly_time":
            profile["weekly_time"],

        "financial_support":
            bool(
                profile["financial_support"]
            ),

        "updated_at":
            now
    }

    insert_data = {
        "user_sub":
            user_sub,

        "email":
            email,

        **update_data,

        "created_at":
            now
    }

    try:

        updated = (
            supabase
            .table("student_profiles")
            .update(update_data)
            .eq("user_sub", user_sub)
            .execute()
        )

        if mutation_row_count(updated) > 0:
            return True

        try:

            upserted = supabase_upsert(
                "student_profiles",
                insert_data,
                "user_sub"
            )

            if mutation_row_count(upserted) > 0:
                return True

            notify_student_data_error()
            return False

        except Exception as upsert_error:

            if not is_missing_conflict_target(
                upsert_error
            ):
                raise

            inserted = (
                supabase
                .table("student_profiles")
                .insert(insert_data)
                .execute()
            )

            if mutation_row_count(inserted) > 0:
                return True

            notify_student_data_error()
            return False

    except Exception as error:

        if is_unique_violation(error):

            retried = (
                supabase
                .table("student_profiles")
                .update(update_data)
                .eq("user_sub", user_sub)
                .execute()
            )

            if mutation_row_count(retried) > 0:
                return True

        log_supabase_exception(
            "save_profile"
        )

        notify_student_data_error()
        return False


