def save_opportunity(user_sub, opportunity_name):

    if not supabase_can_write():
        return False

    if not require_user_sub(user_sub):
        notify_student_data_error()
        return False

    now = datetime.now(
        timezone.utc
    ).isoformat()

    payload = {
        "user_sub":
            user_sub,

        "opportunity_name":
            opportunity_name,

        "status":
            "Saved",

        "notes":
            "",

        "saved_at":
            now,

        "updated_at":
            now
    }

    try:

        existing = (
            supabase
            .table("saved_opportunities")
            .select("id")
            .eq("user_sub", user_sub)
            .eq("opportunity_name", opportunity_name)
            .limit(1)
            .execute()
        )

        if existing.data:
            return True

        try:

            upserted = supabase_upsert(
                "saved_opportunities",
                payload,
                "user_sub,opportunity_name",
                ignore_duplicates=True
            )

            if mutation_row_count(upserted) > 0:
                return True

            # ignore_duplicates may return zero rows when the row already exists.
            verified = (
                supabase
                .table("saved_opportunities")
                .select("id")
                .eq("user_sub", user_sub)
                .eq("opportunity_name", opportunity_name)
                .limit(1)
                .execute()
            )

            if verified.data:
                return True

            notify_student_data_error()
            return False

        except Exception as upsert_error:

            if not is_missing_conflict_target(
                upsert_error
            ):
                raise

            inserted = (
                supabase
                .table("saved_opportunities")
                .insert(payload)
                .execute()
            )

            if mutation_row_count(inserted) > 0:
                return True

            notify_student_data_error()
            return False

    except Exception as error:

        if is_unique_violation(error):
            return True

        log_supabase_exception(
            "save_opportunity"
        )

        notify_student_data_error()
        return False


