def reorder_favorite_colleges(
    user_sub,
    favorite_id,
    direction
):

    if not supabase_can_write():
        return False

    if not require_user_sub(user_sub):
        notify_student_data_error()
        return False

    favorites = load_favorite_colleges(
        user_sub
    )

    if not favorites:
        return False

    current_index = next(
        (
            index
            for index, item
            in enumerate(favorites)
            if item["id"] == favorite_id
        ),
        None
    )

    if current_index is None:
        return False

    if (
        direction == "up"
        and
        current_index == 0
    ):
        return True

    if (
        direction == "down"
        and
        current_index
        == len(favorites) - 1
    ):
        return True

    swap_index = (
        current_index - 1
        if direction == "up"
        else current_index + 1
    )

    current_item = favorites[
        current_index
    ]

    swap_item = favorites[
        swap_index
    ]

    try:

        first_update = (
            supabase
            .table("favorite_colleges")
            .update({
                "rank_order":
                    swap_item[
                        "rank_order"
                    ],

                "updated_at":
                    datetime.now(
                        timezone.utc
                    ).isoformat()
            })
            .eq(
                "id",
                current_item["id"]
            )
            .eq(
                "user_sub",
                user_sub
            )
            .execute()
        )

        second_update = (
            supabase
            .table("favorite_colleges")
            .update({
                "rank_order":
                    current_item[
                        "rank_order"
                    ],

                "updated_at":
                    datetime.now(
                        timezone.utc
                    ).isoformat()
            })
            .eq(
                "id",
                swap_item["id"]
            )
            .eq(
                "user_sub",
                user_sub
            )
            .execute()
        )

        if (
            mutation_row_count(first_update) > 0
            and
            mutation_row_count(second_update) > 0
        ):
            return True

        notify_student_data_error()
        return False

    except Exception:

        log_supabase_exception(
            "reorder_favorite_colleges"
        )

        notify_student_data_error()
        return False


def remove_favorite_college(
    user_sub,
    favorite_id
):

    if not supabase_can_write():
        return False

    if not require_user_sub(user_sub):
        notify_student_data_error()
        return False

    try:

        deleted = (
            supabase
            .table("favorite_colleges")
            .delete()
            .eq("id", favorite_id)
            .eq("user_sub", user_sub)
            .execute()
        )

        if mutation_row_count(deleted) < 1:

            notify_student_data_error()
            return False

        # Re-number remaining favorites so the order stays clean.
        remaining = load_favorite_colleges(
            user_sub
        )

        for index, item in enumerate(
            remaining,
            start=1
        ):

            if item.get(
                "rank_order"
            ) != index:

                ranked = (
                    supabase
                    .table("favorite_colleges")
                    .update({
                        "rank_order":
                            index,

                        "updated_at":
                            datetime.now(
                                timezone.utc
                            ).isoformat()
                    })
                    .eq(
                        "id",
                        item["id"]
                    )
                    .eq(
                        "user_sub",
                        user_sub
                    )
                    .execute()
                )

                if mutation_row_count(ranked) < 1:

                    notify_student_data_error()
                    return False

        return True

    except Exception:

        log_supabase_exception(
            "remove_favorite_college"
        )

        notify_student_data_error()
        return False



