def get_admin_emails():

    try:

        configured = st.secrets.get(
            "admin_emails",
            []
        )

        if isinstance(
            configured,
            str
        ):

            return {
                configured.strip().lower()
            }

        return {
            str(email).strip().lower()
            for email in configured
            if str(email).strip()
        }

    except Exception:

        return set()


def is_admin_user(email):

    admin_emails = get_admin_emails()

    return (
        str(email).strip().lower()
        in admin_emails
    )


